#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Sensor message subscriber example.

This example demonstrates the Python bindings for:
    - ImageSubscriber
    - CompressedImageSubscriber
    - CameraInfoSubscriber
    - RegionOfInterestSubscriber

Each subscriber accepts a topic name from command-line arguments.
"""

import argparse
import signal
import sys
import time


try:
    import booster_robotics_sdk_python as br
except ImportError:
    try:
        import _core as br
    except ImportError:
        print("Error: 'booster_robotics_sdk_python' or '_core' module not found.")
        print("Please ensure the SDK is installed or PYTHONPATH is set correctly.")
        sys.exit(1)


DEFAULT_TOPICS = {
    "image": "rt/booster/camera/color/image_raw",
    "compressed": "rt/booster/camera/color/image_raw/compressed",
    "camera_info": "rt/booster/camera/color/camera_info",
    "roi": "rt/booster/camera/color/roi",
}


def stamp_to_str(stamp) -> str:
    return f"{stamp.sec}.{stamp.nanosec:09d}"


def header_to_str(header) -> str:
    return f"stamp={stamp_to_str(header.stamp)}, frame_id='{header.frame_id}'"


def preview_bytes(data, limit: int = 8) -> str:
    values = list(data[:limit])
    suffix = "" if len(data) <= limit else "..."
    return f"{values}{suffix}"


def on_image(msg):
    print(
        "[Image]",
        header_to_str(msg.header),
        f"size={msg.width}x{msg.height}",
        f"encoding={msg.encoding}",
        f"bigendian={msg.is_bigendian}",
        f"step={msg.step}",
        f"data_len={len(msg.data)}",
        f"data[:8]={preview_bytes(msg.data)}",
    )


def on_compressed_image(msg):
    print(
        "[CompressedImage]",
        header_to_str(msg.header),
        f"format={msg.format}",
        f"data_len={len(msg.data)}",
        f"data[:8]={preview_bytes(msg.data)}",
    )


def on_camera_info(msg):
    roi = msg.roi
    print(
        "[CameraInfo]",
        header_to_str(msg.header),
        f"size={msg.width}x{msg.height}",
        f"distortion_model={msg.distortion_model}",
        f"d_len={len(msg.d)}",
        f"k={list(msg.k)}",
        f"p={list(msg.p)}",
        "roi="
        f"(x={roi.x_offset}, y={roi.y_offset}, w={roi.width}, "
        f"h={roi.height}, rectify={roi.do_rectify})",
    )


def on_roi(msg):
    print(
        "[RegionOfInterest]",
        f"x={msg.x_offset}",
        f"y={msg.y_offset}",
        f"width={msg.width}",
        f"height={msg.height}",
        f"do_rectify={msg.do_rectify}",
    )


def parse_switches(raw: str, valid: set) -> set:
    value = raw.strip().lower()
    if value == "all":
        return set(valid)
    if value == "none" or not value:
        return set()

    selected = set()
    for item in value.split(","):
        key = item.strip()
        if not key:
            continue
        if key not in valid:
            print(f"[Warn] unknown subscription '{key}', ignored.")
            continue
        selected.add(key)
    return selected


def parse_args():
    parser = argparse.ArgumentParser(
        description="Subscribe to sensor_msgs topics through booster SDK Python bindings."
    )
    parser.add_argument(
        "--domain-id",
        type=int,
        default=0,
        help="DDS domain id (default: 0)",
    )
    parser.add_argument(
        "--iface",
        type=str,
        default="",
        help="DDS network interface, for example eth0/eno1 (default: auto)",
    )
    parser.add_argument(
        "--subs",
        type=str,
        default="all",
        help="Comma-separated: image,compressed,camera_info,roi,all,none",
    )
    parser.add_argument(
        "--image-topic",
        type=str,
        default=DEFAULT_TOPICS["image"],
        help=f"Image topic (default: {DEFAULT_TOPICS['image']})",
    )
    parser.add_argument(
        "--compressed-topic",
        type=str,
        default=DEFAULT_TOPICS["compressed"],
        help=f"CompressedImage topic (default: {DEFAULT_TOPICS['compressed']})",
    )
    parser.add_argument(
        "--camera-info-topic",
        type=str,
        default=DEFAULT_TOPICS["camera_info"],
        help=f"CameraInfo topic (default: {DEFAULT_TOPICS['camera_info']})",
    )
    parser.add_argument(
        "--roi-topic",
        type=str,
        default=DEFAULT_TOPICS["roi"],
        help=f"RegionOfInterest topic (default: {DEFAULT_TOPICS['roi']})",
    )
    parser.add_argument(
        "--duration",
        type=float,
        default=0.0,
        help="Run duration in seconds. 0 means run until Ctrl+C (default: 0)",
    )
    return parser.parse_args()


def main():
    args = parse_args()
    valid_subs = {"image", "compressed", "camera_info", "roi"}
    enabled_subs = parse_switches(args.subs, valid_subs)

    topic_by_sub = {
        "image": args.image_topic,
        "compressed": args.compressed_topic,
        "camera_info": args.camera_info_topic,
        "roi": args.roi_topic,
    }

    if not enabled_subs:
        print("No subscribers enabled. Use --subs image,compressed,camera_info,roi or --subs all.")
        return

    print(f"Initializing ChannelFactory: domain_id={args.domain_id}, iface='{args.iface}'")
    br.ChannelFactory.Instance().Init(args.domain_id, args.iface)

    subscribers = []

    if "image" in enabled_subs:
        sub = br.ImageSubscriber(on_image, topic_by_sub["image"])
        sub.InitChannel()
        subscribers.append(sub)

    if "compressed" in enabled_subs:
        sub = br.CompressedImageSubscriber(
            on_compressed_image, topic_by_sub["compressed"]
        )
        sub.InitChannel()
        subscribers.append(sub)

    if "camera_info" in enabled_subs:
        sub = br.CameraInfoSubscriber(on_camera_info, topic_by_sub["camera_info"])
        sub.InitChannel()
        subscribers.append(sub)

    if "roi" in enabled_subs:
        sub = br.RegionOfInterestSubscriber(on_roi, topic_by_sub["roi"])
        sub.InitChannel()
        subscribers.append(sub)

    print("Enabled subscribers:")
    for sub in subscribers:
        print(f"  - {sub.GetChannelName()}")

    running = True

    def handle_sigint(_sig, _frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, handle_sigint)

    started_at = time.monotonic()
    print("\n[Running] Waiting for messages. Press Ctrl+C to exit.\n")

    try:
        while running:
            if args.duration > 0.0 and time.monotonic() - started_at >= args.duration:
                break
            time.sleep(0.05)
    finally:
        print("\nClosing channels...")
        for sub in subscribers:
            sub.CloseChannel()
        print("Done.")


if __name__ == "__main__":
    main()
